    "WP-001",
    "WP-008"
  ],
  "acceptance_criteria": [
    {
      "criterion": "`renderWorkPackageDetail` accepts `(app, repo, slug, wpId)` and passes `(repo, slug)` to all API calls",
      "met": true
    },
    {
      "criterion": "`renderRunLog` accepts `(app, repo, slug, filename)` and passes `(repo, slug)` to all API calls",
      "met": true
    },
    {
      "criterion": "No API call or link in either view still uses the bare-slug form",
      "met": true
    },
    {
      "criterion": "`resolveProjectStore()` catch block logs caught errors to stderr",
      "met": true
    },
    {
      "criterion": "Log output includes sufficient context (error message, slug/repo parameters) for operator diagnostics",
      "met": true
    },
    {
      "criterion": "No change to the function's return value or error-handling behavior (logging is additive only)",
      "met": true
    }
  ],
  "active_pipeline_stages": [
    "implementation",
    "qa",
    "code-review",
    "documentation"
  ],
  "revision": 0,
  "pipelines": [
    {
      "type": "implementation",
      "status": "PASS",
      "started_at": "2026-05-31T17:13:06Z",
      "completed_at": "2026-05-31T17:20:49Z",
      "duration_ms": 463000,
      "summary": [
        "Updated `renderWorkPackageDetail` in work-package.js to accept `(app, repo, slug, wpId)` and pass `(repo, slug)` to all API calls: `getWorkPackage`, `getChunks`, `getDialogues`, `getChunkRendered`, `getDialogueContent`. Added `data-repo` attribute to dialogue buttons and updated click handler to read it.",
        "Updated `renderRunLog` in run-log.js to accept `(app, repo, slug, filename)` and pass `(repo, slug)` to both `getRunLogEntries` calls (initial load and incremental poll). Updated breadcrumb to `project(repo, slug)`.",
