  1	/* ============================================================
  2	   views/run-log.js — Orchestrator Run Log Viewer
  3	   Section 4e of the MCP Server Dashboard SPA
  4	
  5	   Depends on: API, Router, escapeHtml, formatDate, showLoading, showError
  6	   ============================================================ */
  7	
  8	/* ----------------------------------------------------------
  9	   Event card renderers
 10	   ---------------------------------------------------------- */
 11	
 12	/**
 13	 * Returns a CSS severity class for an event action type.
 14	 *
 15	 * - error / fail actions → run-event--error
 16	 * - warning-ish          → run-event--warning
 17	 * - success outcomes     → run-event--success
 18	 * - default              → run-event--info
 19	 */
 20	function runEventSeverity(action) {
 21	  if (action === 'run_error' || action === 'stage_error' || action === 'halted_repeated_failure') return 'run-event--error';
 22	  if (action === 'safety_limit' || action === 'rework_detected' || action === 'mcp_error' || action === 'dry_run_no_ledger') return 'run-event--warning';
 23	  if (action === 'wp_complete' || action === 'run_end' || action === 'dry_run_complete') return 'run-event--success';
 24	  if (action === 'tool_call') return 'run-event--debug';
 25	  return 'run-event--info';
 26	}
 27	
 28	/**
 29	 * Formats a duration in seconds to a human-readable string.
 30	 * @param {number|null|undefined} sec - Duration in seconds.
 31	 * @returns {string} Formatted string (e.g. "3m 24s") or empty string.
 32	 */
 33	function formatDurationSec(sec) {
 34	  if (sec == null || isNaN(sec)) return '';
 35	  return formatDuration(sec * 1000);
 36	}
 37	
 38	/**
 39	 * Formats a token count to a compact human-readable string (e.g. "72k").
 40	 * @param {object|number|null} tokens - Token usage object or raw number.
 41	 * @returns {string} Formatted string or empty string.
 42	 */
 43	function formatTokens(tokens) {
 44	  if (tokens == null) return '';
 45	  var total = typeof tokens === 'number' ? tokens : (tokens.total_tokens || 0);
 46	  if (!total) return '';
 47	  if (total >= 1000) return Math.round(total / 1000) + 'k tokens';
 48	  return total + ' tokens';
 49	}
 50	
 51	/**
 52	 * Builds the inner content HTML for a single event entry.
 53	 * Handles known action types explicitly; falls back to a generic card.
 54	 *
 55	 * @param {object} entry - A parsed log entry object.
 56	 * @returns {string} HTML string for the card body.
 57	 */
 58	function buildRunEventContent(entry) {
 59	  const action = entry && entry.action ? String(entry.action) : 'unknown';
 60	
 61	  switch (action) {
 62	
 63	    // ── Orchestrator lifecycle ───────────────────────────────────────
 64	    case 'run_start': {
 65	      const threadId = entry.thread_id ? escapeHtml(String(entry.thread_id)) : '';
 66	      const plan = entry.plan ? String(entry.plan) : '';
 67	      // Show just the plan filename, not the full path
 68	      const planName = plan ? escapeHtml(plan.split('/').pop() || plan) : '';
 69	      const dryRunBadge = entry.dry_run ? ' <span class="badge badge-dry-run">Dry Run</span>' : '';
 70	      let html = '<strong>Run started</strong>' + dryRunBadge;
 71	      if (planName) html += ' &mdash; ' + planName;
 72	      if (threadId) html += '<br><span class="text-muted monospace" style="font-size:11px">Thread: ' + threadId + '</span>';
 73	      return html;
 74	    }
 75	    case 'run_end': {
 76	      const dur = entry.total_duration_s != null ? formatDurationSec(entry.total_duration_s) : '';
 77	      return '<strong>Run completed</strong>' + (dur ? ' <span class="text-muted">(' + escapeHtml(dur) + ')</span>' : '');
 78	    }
 79	    case 'run_error': {
 80	      const errMsg = entry.error ? escapeHtml(String(entry.error)) : 'Unknown error';
 81	      return '<strong>Run error:</strong> ' + errMsg;
 82	    }
 83	
 84	    // ── Stage events ─────────────────────────────────────────────────
 85	    case 'stage_start': {
 86	      const wpId = entry.wp_id ? escapeHtml(String(entry.wp_id)) : '';
 87	      const stg = entry.stage ? escapeHtml(String(entry.stage).replace(/_/g, ' ')) : '';
 88	      const iter = entry.iteration ? ' <span class="text-muted">(iteration ' + escapeHtml(String(entry.iteration)) + ')</span>' : '';
 89	      return '<strong>Stage started</strong>' +
 90	        (stg ? ' &mdash; <em>' + stg + '</em>' : '') +
 91	        (wpId ? ' for <strong>' + wpId + '</strong>' : '') +
 92	        iter;
 93	    }
 94	    case 'stage_complete': {
 95	      const wpId = entry.wp_id ? escapeHtml(String(entry.wp_id)) : '';
 96	      const result = entry.result ? escapeHtml(String(entry.result)) : '';
 97	      const dur = formatDurationSec(entry.duration_s);
 98	      const tok = formatTokens(entry.tokens_used);
 99	      const details = [];
100	      if (dur) details.push(dur);

  1	/* ============================================================
  2	   views/work-package.js — Work Package Detail view
  3	   Section 4c of the MCP Server Dashboard SPA
  4	   Depends on: API, escapeHtml, formatDate, statusBadge,
  5	               showLoading, showError, STAGE_ABBREV (project-detail.js)
  6	   ============================================================ */
  7	
  8	var WP_DEFAULT_STAGES = ['implementation', 'qa', 'code-review', 'documentation'];
  9	
 10	function buildWpDetailBar(wp) {
 11	  var rawStages = (wp.active_pipeline_stages && wp.active_pipeline_stages.length)
 12	    ? wp.active_pipeline_stages
 13	    : (wp.default_pipeline_stages && wp.default_pipeline_stages.length)
 14	      ? wp.default_pipeline_stages
 15	      : WP_DEFAULT_STAGES;
 16	
 17	  // Build a fast lookup from pipeline type → latest pipeline status
 18	  var latestStatus = {};
 19	  var pipelineCountByType = {};
 20	  (wp.pipelines || []).forEach(function (p) {
 21	    var t = p.type;
 22	    pipelineCountByType[t] = (pipelineCountByType[t] || 0) + 1;
 23	    // Last write wins — pipelines are in chronological order
 24	    latestStatus[t] = (p.status || '').toLowerCase();
 25	  });
 26	
 27	  var badges = rawStages.map(function (stageType) {
 28	    var abbrev = (typeof STAGE_ABBREV !== 'undefined' && STAGE_ABBREV[stageType])
 29	      ? STAGE_ABBREV[stageType]
 30	      : stageType.slice(0, 3).toUpperCase();
 31	    var rawSt = latestStatus[stageType] || 'pending';
 32	    var statusClass = 'stage-pending';
 33	    if (rawSt === 'in_progress' || rawSt === 'in-progress') statusClass = 'stage-in-progress';
 34	    else if (rawSt === 'pass')                               statusClass = 'stage-pass';
 35	    else if (rawSt === 'fail')                               statusClass = 'stage-fail';
 36	
 37	    var reworkCount = wp.rework_counts ? (wp.rework_counts[stageType] || 0) : 0;
 38	    if (!reworkCount && pipelineCountByType[stageType] > 1) {
 39	      reworkCount = pipelineCountByType[stageType] - 1;
 40	    }
 41	    var tooltip = escapeHtml(stageType);
 42	    if (rawSt !== 'pending') tooltip += ' — ' + escapeHtml(rawSt);
 43	    if (reworkCount > 0)     tooltip += ' (rework: ' + reworkCount + ')';
 44	    var reworkBadge = reworkCount > 0
 45	      ? '<span class="rework-indicator" title="Rework count: ' + reworkCount + '">' + reworkCount + '</span>'
 46	      : '';
 47	    return '<span class="stage-badge ' + statusClass + '" title="' + tooltip + '">' +
 48	      escapeHtml(abbrev) + reworkBadge +
 49	    '</span>';
 50	  }).join('');
 51	
 52	  return '<div class="card">' +
 53	    '<div class="card-title" style="margin-bottom:8px">Pipeline Progression</div>' +
 54	    '<div class="pipeline-track">' + badges + '</div>' +
 55	  '</div>';
 56	}
 57	
 58	function renderWorkPackageDetail(app, repo, slug, wpId) {
 59	  showLoading(app);
 60	
 61	  API.getWorkPackage(repo, slug, wpId).then(function (wp) {
 62	    // Acceptance criteria
 63	    var acHtml = (wp.acceptance_criteria || []).map(function (ac) {
 64	      var met = ac.met === true;
 65	      return '<li>' +
 66	        '<span class="ac-icon ' + (met ? 'ac-met' : 'ac-unmet') + '">' + (met ? '✓' : '○') + '</span>' +
 67	        '<span>' + escapeHtml(ac.criterion) + '</span>' +
 68	      '</li>';
 69	    }).join('');
 70	
 71	    // WP aggregate timing
 72	    var totalActiveMs = 0;
 73	    var hasDurationData = false;
 74	    var firstStartAt = null;
 75	    var lastCompletedAt = null;
 76	    (wp.pipelines || []).forEach(function (p) {
 77	      if (p.duration_ms != null) {
 78	        totalActiveMs += p.duration_ms;
 79	        hasDurationData = true;
 80	      }
 81	      if (p.started_at) {
 82	        var tsStart = new Date(p.started_at).getTime();
 83	        if (!isNaN(tsStart) && (firstStartAt === null || tsStart < firstStartAt)) firstStartAt = tsStart;
 84	      }
 85	      if (p.completed_at) {
 86	        var tsEnd = new Date(p.completed_at).getTime();
 87	        if (!isNaN(tsEnd) && (lastCompletedAt === null || tsEnd > lastCompletedAt)) lastCompletedAt = tsEnd;
 88	      }
 89	    });
 90	    var wallClockMs = (firstStartAt !== null && lastCompletedAt !== null) ? (lastCompletedAt - firstStartAt) : null;
 91	    var wpTimingHtml = (hasDurationData || wallClockMs !== null)
 92	      ? '<div class="wp-timing">' +
 93	          (hasDurationData ? '<strong>Active time:</strong> ' + escapeHtml(formatDuration(totalActiveMs)) : '') +
 94	          (hasDurationData && wallClockMs !== null ? ' &nbsp;·&nbsp; ' : '') +
 95	          (wallClockMs !== null ? '<strong>Wall-clock:</strong> ' + escapeHtml(formatDuration(wallClockMs)) : '') +
 96	        '</div>'
 97	      : '';
 98	
 99	    // Pipelines
100	    var pipelinesHtml = (wp.pipelines || []).slice().reverse().map(function (p) {

101	      if (tok) details.push(tok);
102	      const resultClass = result === 'PASS' ? 'badge badge-pass' : (result === 'FAIL' ? 'badge badge-fail' : 'badge badge-neutral');
103	      return '<strong>Stage complete</strong>' +
